-- OFERTAS V2 (C8 da change `planos-v2`, ADR 0011) — os textos da matriz v2 no payload de `oferta_planos`.
-- `docs/ofertas.md`, `docs/flags.md`.
--
-- A semente da 0039 vendia "os planos pagos" e a IA de nuvem "mais precisa que a do aparelho" — vender qualidade
-- pega mal (decisão do dono) e já não há dois planos pagos. A 0041 só tirou o `essencial` das listas e deixou o
-- payload novo para cá. Os seis gatilhos continuam (mesmos ids, momentos, componentes e frequências), com:
--   - textos do Premium: a Tradução Nuance ao tocar numa frase, a nuvem, e o aparelho que segue SEM LIMITE —
--     nenhum "sem limite no dia a dia" (que exigiria a nota do uso justo ao lado), nenhum número de qualidade;
--   - `variante: "v2"` em todos: as métricas do funil (`oferta_eventos_por_plano_total{variante}`) separam a
--     conversão dos textos novos da dos antigos (`padrao`);
--   - `planos`: a venda só para o Grátis e a conta só para o convidado (o Premium nunca é alvo promocional).
-- O motor aplica, além disso, o portão novo do C8 (`src/lib/ofertas/motor.ts`): a conta de perfil protegido não
-- lê este payload — recebe só os avisos funcionais EMBUTIDOS, sem venda. E a sugestão do teste de 14 dias vem do
-- selo do host ("Sugerido: 14 dias de Premium grátis, sem cartão"), não do texto: aqui não se promete o teste a
-- quem já testou.
--
-- NÚMERO 0045 porque a 0044 está reservada para a Fase D (outra branch). No merge, o `when` da 0044 no journal
-- precisa ficar MENOR que o desta (o migrador do drizzle pula a migration com `when` anterior à última aplicada).
--
-- SÓ A LINHA DA SEMENTE (`atualizado_por = 'semente'`): se o operador já mexeu na flag pelo admin ou pela CLI, a
-- escolha dele vale e esta migração não faz nada. Não liga nem desliga a flag. Reaplicar escreve os mesmos
-- valores (idempotente). Aditiva (expand): só dado; o código anterior lê o mesmo formato de payload (a
-- `variante` já existia no schema).
-- REVERSAO: reaplicar o UPDATE da 0039 e o UPDATE do payload da 0041 (os textos antigos, sem o `essencial`), ou
-- editar o payload pelo admin; desligar a flag (`flags desligar oferta_planos`) tira todas as promocionais na hora.
UPDATE flags SET
  descricao = 'Fase 8: banners, modais e paywall de planos. O payload define gatilhos, textos e frequência. Ligada desde a 0039; textos da matriz v2 (Premium) desde a 0045.',
  payload = '{"gatilhos":[{"id":"cota_acabou","momento":"fim_de_cota","componente":"modal","titulo":{"pt":"A nuvem grátis do mês acabou","en":"This month''s free cloud is used up","es":"Se acabó la nube gratis del mes"},"texto":{"pt":"A legenda continua no seu aparelho, sem limite. Com o Premium, a transcrição e a tradução voltam para a nuvem.","en":"Captions continue on your device, unlimited. With Premium, transcription and translation go back to the cloud.","es":"Los subtítulos siguen en tu dispositivo, sin límite. Con Premium, la transcripción y la traducción vuelven a la nube."},"cta":{"pt":"Conhecer o Premium","en":"Discover Premium","es":"Conocer Premium"},"maxPorDia":1,"maxPorSemana":3,"intervaloMinHoras":12,"planos":["free"],"variante":"v2"},{"id":"cota_perto","momento":"cota_proxima","componente":"aviso_cota","titulo":{"pt":"A nuvem grátis do mês está no fim","en":"This month''s free cloud is almost used up","es":"La nube gratis del mes está por acabarse"},"texto":{"pt":"Quando ela acabar, a legenda continua no seu aparelho, sem limite.","en":"When it runs out, captions continue on your device, unlimited.","es":"Cuando se acabe, los subtítulos siguen en tu dispositivo, sin límite."},"cta":{"pt":"Ver planos","en":"See plans","es":"Ver planes"},"maxPorDia":1,"maxPorSemana":2,"intervaloMinHoras":24,"planos":["free"],"variante":"v2"},{"id":"premium","momento":"modelo_premium","componente":"comparacao","titulo":{"pt":"A IA de nuvem está no Premium","en":"Cloud AI is in Premium","es":"La IA en la nube está en Premium"},"texto":{"pt":"Com o Premium, a transcrição e a tradução usam a nuvem, e ao tocar numa frase a Tradução Nuance mostra outras formas de dizer.","en":"With Premium, transcription and translation use the cloud, and tapping a sentence shows other ways to say it with Nuance Translation.","es":"Con Premium, la transcripción y la traducción usan la nube, y al tocar una frase la Traducción Nuance muestra otras formas de decirlo."},"cta":{"pt":"Conhecer o Premium","en":"Discover Premium","es":"Conocer Premium"},"maxPorDia":2,"maxPorSemana":5,"intervaloMinHoras":2,"planos":["free"],"variante":"v2"},{"id":"criar_conta","momento":"convidado_para_conta","componente":"banner","titulo":{"pt":"Guarde seu progresso","en":"Keep your progress","es":"Guarda tu progreso"},"texto":{"pt":"Crie uma conta para levar seus cartões e sessões para outros aparelhos.","en":"Create an account to take your cards and sessions to other devices.","es":"Crea una cuenta para llevar tus tarjetas y sesiones a otros dispositivos."},"cta":{"pt":"Criar conta","en":"Create account","es":"Crear cuenta"},"maxPorDia":1,"maxPorSemana":3,"intervaloMinHoras":24,"planos":["convidado"],"variante":"v2"},{"id":"fim_sessao","momento":"fim_de_sessao","componente":"banner","titulo":{"pt":"Boa sessão!","en":"Nice session!","es":"¡Buena sesión!"},"texto":{"pt":"No Premium, toque numa frase para ver outras formas de dizer e escolher entre formal e informal.","en":"On Premium, tap a sentence to see other ways to say it and choose between formal and informal.","es":"En Premium, toca una frase para ver otras formas de decirla y elegir entre formal e informal."},"cta":{"pt":"Conhecer o Premium","en":"Discover Premium","es":"Conocer Premium"},"maxPorDia":1,"maxPorSemana":2,"intervaloMinHoras":24,"planos":["free"],"variante":"v2"},{"id":"conquista","momento":"conquista","componente":"banner","titulo":{"pt":"Mais uma conquista","en":"Another achievement","es":"Otro logro"},"texto":{"pt":"Quer ir além da tradução rápida? A Tradução Nuance do Premium mostra o jeito de dizer.","en":"Want to go beyond fast translation? Premium''s Nuance Translation shows how things are said.","es":"¿Quieres ir más allá de la traducción rápida? La Traducción Nuance de Premium muestra cómo se dice."},"cta":{"pt":"Conhecer o Premium","en":"Discover Premium","es":"Conocer Premium"},"maxPorDia":1,"maxPorSemana":2,"intervaloMinHoras":48,"planos":["free"],"variante":"v2"}]}',
  atualizado_em = 1790780000000
WHERE chave = 'oferta_planos' AND atualizado_por = 'semente';
